fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo and choose 'Credentials', then open the 'Categories' section. Pages can take 10-30s to load — wait, don't navigate away. Verify a hierarchical category tree renders with indentation for nested categories (or a valid empty state). Use the 'Expand' and 'Collapse' buttons in the top-right (and/or per-node chevrons) and confirm the visible tree depth changes. Then click a category node to open its detail panel showing subcategory and credential-type counts.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
